#include <os/list.h>
#include <os/mm.h>
#include <os/sched.h>
#include <pgtable.h>
#include <os/string.h>
#include <os/sched.h>
#include <os/irq.h>
#include <assert.h>

ptr_t kernel_memCurr = KERNEL_MEM_BEGIN;
ptr_t user_memCurr = USER_MEM_BEGIN;

user_page_t user_page[USER_PAGE_NUM];
shm_page_t shm_page[SHM_PAGE_NUM];
disk_page_t disk_page[DISK_PAGE_NUM];
pgdir_page_t pgdir_page[PGDIR_PAGE_NUM];

// returns pa
PTE* alloc_pgdir_page()
{
    int i;
    for(i = 0; i < PGDIR_PAGE_NUM; i++){
        if(pgdir_page[i].valid == 0){
            break;
        }
    }
    assert(i != PGDIR_PAGE_NUM);
    pgdir_page[i].valid = 1;
    PTE *ret = (PTE*)(FREE_PGDIR_ADDR + i * PAGE_SIZE);
    clear_pgdir((PTE*)pa2kva((uintptr_t)ret));
    return ret;
}

void free_pgdir_page(uintptr_t addr)
{
    int i = (addr - FREE_PGDIR_ADDR) / PAGE_SIZE;
    pgdir_page[i].valid = 0;
}

int pa2num(uintptr_t pa)
{
    return (pa - USER_MEM_BEGIN) / PAGE_SIZE;
}
ptr_t num2pa(int num)
{
    return (USER_MEM_BEGIN + num * PAGE_SIZE);
}

// returns pa
ptr_t alloc_user_page(uint8_t pin, PTE* pgtable)
{
    int i;
    for(i = 0; i < USER_PAGE_NUM; i++){
        if(user_page[i].valid == 0){
            break;
        }
    }

    ptr_t pa;
    if(i == USER_PAGE_NUM){
        /* physical memory is exhausted: swap somebody else out first */
        pa = selete_page();
        write_to_sd(pa);
        i = pa2num(pa);
    }
    else{
        pa = num2pa(i);
    }

    user_page[i].valid = 1;
    user_page[i].pin = pin;
    user_page[i].pgtable = pgtable;

    /* a fresh page must not leak the previous owner's data */
    memset((void*)pa2kva(pa), 0, PAGE_SIZE);
    return pa;
}

// baseAddr is pa
void free_user_page(ptr_t baseAddr)
{
    user_page[pa2num(baseAddr)].valid = 0;
}

// returns pa
void *kmalloc(size_t size)
{
    // align 4
    ptr_t ret = ROUND(kernel_memCurr, 4);
    kernel_memCurr = ret + size;
    return (void*)ret;
}

// select a user page to write to disk (NRU), returns pa
ptr_t selete_page()
{
    /* Not Recently Used with a second chance: sweep the frames, give every
     * page whose accessed bit is set one more round (clearing the bit as we
     * pass by), and evict the first one that survived a whole sweep unused.
     * Pinned frames (kernel stacks, shared pages) and frames that are not
     * reachable through a page table entry can never be evicted. */
    static int clock_hand = 0;

    for(int step = 0; step < 2 * USER_PAGE_NUM; step++){
        int i = clock_hand;
        clock_hand = (clock_hand + 1) % USER_PAGE_NUM;

        if(!user_page[i].valid || user_page[i].pin || user_page[i].pgtable == NULL){
            continue;
        }
        if(get_attribute(*user_page[i].pgtable, _PAGE_ACCESSED)){
            clear_attribute(user_page[i].pgtable, _PAGE_ACCESSED);
            continue;
        }
        return num2pa(i);
    }

    /* every single frame is pinned, there is nothing we can do */
    assert(0);
    return 0;
}

void write_to_sd(ptr_t pa)
{
    int i;
    for(i = 0; i < DISK_PAGE_NUM; i++){
        if(disk_page[i].valid == 0){
            break;
        }
    }
    assert(i != DISK_PAGE_NUM);
    disk_page[i].valid = 1;

    sbi_sd_write((unsigned int)pa, PAGE_SD_BLOCKS, SWAP_BEGIN + i * PAGE_SD_BLOCKS);

    /* Remember where the page went inside its own page table entry: the
     * frame number field now holds the swap slot and _PAGE_SOFT marks the
     * entry as "on disk" so that the page fault handler can tell it apart
     * from a never-mapped address. */
    PTE *pgtable = user_page[pa2num(pa)].pgtable;
    if(pgtable != NULL){
        clear_attribute(pgtable, _PAGE_PRESENT);
        set_attribute(pgtable, _PAGE_SOFT);
        set_pfn(pgtable, (uint64_t)i);
    }

    flush_tlb_all();
    free_user_page(pa);
}

unsigned long free_page_num()
{
    unsigned long ret = 0;
    for(int i = 0; i < USER_PAGE_NUM; i++){
        if(user_page[i].valid == 0){
            ret++;
        }
    }
    return ret;
}

/* Walk the three levels of `pgdir` (a pa) down to the leaf entry for `va`,
 * creating the intermediate tables on the way. Returns a pointer to the leaf
 * PTE, which the caller reaches through the kernel's direct mapping. */
static PTE* walk_pgdir(uintptr_t va, uintptr_t pgdir)
{
    uint64_t vpn[3];
    vpn[2] = (va >> VPN2_SHIFT) & VPN_MASK;
    vpn[1] = (va >> VPN1_SHIFT) & VPN_MASK;
    vpn[0] = (va >> VPN0_SHIFT) & VPN_MASK;

    PTE *table = (PTE*)pa2kva(pgdir);
    for(int level = 2; level > 0; level--){
        PTE *entry = table + vpn[level];
        if(!get_attribute(*entry, _PAGE_PRESENT)){
            PTE *next = alloc_pgdir_page();
            *entry = 0;
            set_pfn(entry, (uintptr_t)next >> NORMAL_PAGE_SHIFT);
            /* a pointer entry carries no R/W/X bits */
            set_attribute(entry, _PAGE_PRESENT);
        }
        table = (PTE*)pa2kva(get_pa(*entry));
    }
    return table + vpn[0];
}

/* Same walk, but without creating anything: returns NULL when the address is
 * not backed by a leaf entry at all. */
PTE* find_pte(uintptr_t va, uintptr_t pgdir)
{
    uint64_t vpn[3];
    vpn[2] = (va >> VPN2_SHIFT) & VPN_MASK;
    vpn[1] = (va >> VPN1_SHIFT) & VPN_MASK;
    vpn[0] = (va >> VPN0_SHIFT) & VPN_MASK;

    PTE *table = (PTE*)pa2kva(pgdir);
    for(int level = 2; level > 0; level--){
        PTE *entry = table + vpn[level];
        if(!get_attribute(*entry, _PAGE_PRESENT)){
            return NULL;
        }
        table = (PTE*)pa2kva(get_pa(*entry));
    }
    return table + vpn[0];
}

/*
 * Make sure `va` is backed by a physical frame in `pgdir` (a pa) and return
 * the kernel virtual address of that frame.  A page that had been swapped out
 * is read back from the SD card first.  The signature matches the callback
 * load_elf() expects, so it doubles as the "prepare page" hook of do_exec().
 */
uintptr_t alloc_page_helper(uintptr_t va, uintptr_t pgdir)
{
    va = ROUNDDOWN(va, PAGE_SIZE);
    PTE *pte = walk_pgdir(va, pgdir);

    if(!get_attribute(*pte, _PAGE_PRESENT)){
        if(get_attribute(*pte, _PAGE_SOFT)){
            /* the page lives in the swap area, fetch it back */
            uint64_t slot = get_pfn(*pte);
            uintptr_t pa = alloc_user_page(0, pte);
            sbi_sd_read((unsigned int)pa, PAGE_SD_BLOCKS, SWAP_BEGIN + slot * PAGE_SD_BLOCKS);
            disk_page[slot].valid = 0;
            *pte = 0;
            set_pfn(pte, pa >> NORMAL_PAGE_SHIFT);
        }
        else{
            uintptr_t pa = alloc_user_page(0, pte);
            *pte = 0;
            set_pfn(pte, pa >> NORMAL_PAGE_SHIFT);
        }
        set_attribute(pte, _PAGE_PRESENT | _PAGE_READ | _PAGE_WRITE | _PAGE_EXEC |
                           _PAGE_USER | _PAGE_ACCESSED | _PAGE_DIRTY);
        flush_tlb_all();
    }

    return pa2kva(get_pa(*pte));
}

/*
 * Virtual Memory Layout
 * 0x0_0000_1000 ~ 0x0_0001_0000: share
 * 0x0_0001_0000 ~ 0x0_0001_3000: code
 * 0xf_0000_f000 ~ 0xf_0001_0000: stack
 */
PTE* init_page_table()
{
    PTE *pgdir = alloc_pgdir_page();
    PTE *pgdir_kva = (PTE*)pa2kva((uintptr_t)pgdir);
    PTE *kernel_pgdir_kva = (PTE*)pa2kva(PGDIR_PA);

    /* Every address space keeps the kernel mapped: VPN2 of the kernel window
     * 0xffffffc0_00000000 is 0x101 and boot.c installed it there. */
    pgdir_kva[0x101] = kernel_pgdir_kva[0x101];

    /* init_pcb() resolves addresses with get_kva_of(), which only walks the
     * table, so the whole code region has to be mapped up front. */
    for(uintptr_t va = USER_CODE_BEGIN; va < USER_CODE_END; va += PAGE_SIZE){
        alloc_page_helper(va, (uintptr_t)pgdir);
    }
    /* and one page of user stack to start on */
    alloc_page_helper(USER_STACK_ADDR - PAGE_SIZE, (uintptr_t)pgdir);

    return pgdir;
}

void free_process_user_page(PTE* pgdir)
{
    if(pgdir == NULL || (uintptr_t)pgdir == PGDIR_PA){
        return;
    }

    PTE *pgdir_kva = (PTE*)pa2kva((uintptr_t)pgdir);

    /* Only the user half is owned by this process; VPN2 >= 0x100 belongs to
     * the kernel window, which is shared by everybody. */
    for(int vpn2 = 0; vpn2 < NUM_PTE_ENTRY / 2; vpn2++){
        if(!get_attribute(pgdir_kva[vpn2], _PAGE_PRESENT)){
            continue;
        }
        uintptr_t second_pa = get_pa(pgdir_kva[vpn2]);
        PTE *second_kva = (PTE*)pa2kva(second_pa);

        for(int vpn1 = 0; vpn1 < NUM_PTE_ENTRY; vpn1++){
            if(!get_attribute(second_kva[vpn1], _PAGE_PRESENT)){
                continue;
            }
            uintptr_t third_pa = get_pa(second_kva[vpn1]);
            PTE *third_kva = (PTE*)pa2kva(third_pa);

            for(int vpn0 = 0; vpn0 < NUM_PTE_ENTRY; vpn0++){
                PTE leaf = third_kva[vpn0];
                if(leaf == 0){
                    continue;
                }
                if(get_attribute(leaf, _PAGE_PRESENT)){
                    uintptr_t pa = get_pa(leaf);
                    int shared = 0;
                    /* a shared page only goes away with its last user */
                    for(int k = 0; k < SHM_PAGE_NUM; k++){
                        if(shm_page[k].count > 0 && shm_page[k].pa == pa){
                            shm_page[k].count--;
                            if(shm_page[k].count == 0){
                                free_user_page(pa);
                                shm_page[k].pa = 0;
                            }
                            shared = 1;
                            break;
                        }
                    }
                    if(!shared){
                        free_user_page(pa);
                    }
                }
                else if(get_attribute(leaf, _PAGE_SOFT)){
                    /* the page was swapped out, give the disk slot back */
                    disk_page[get_pfn(leaf)].valid = 0;
                }
                third_kva[vpn0] = 0;
            }

            free_pgdir_page(third_pa);
            second_kva[vpn1] = 0;
        }

        free_pgdir_page(second_pa);
        pgdir_kva[vpn2] = 0;
    }

    free_pgdir_page((uintptr_t)pgdir);
    flush_tlb_all();
}

uintptr_t shm_page_get(int key)
{
    shm_page_t *page = &shm_page[(uint32_t)key % SHM_PAGE_NUM];

    if(page->count == 0){
        /* first user of this key: give the group a pinned frame, it must
         * never be swapped out behind the back of the other sharers */
        page->pa = alloc_user_page(1, NULL);
    }

    uintptr_t pgdir = (uintptr_t)current_running[cpu_id]->pgdir;
    for(uintptr_t va = SHM_VA_BEGIN; va < SHM_VA_END; va += PAGE_SIZE){
        PTE *pte = walk_pgdir(va, pgdir);
        if(get_attribute(*pte, _PAGE_PRESENT) || get_attribute(*pte, _PAGE_SOFT)){
            continue;
        }
        *pte = 0;
        set_pfn(pte, page->pa >> NORMAL_PAGE_SHIFT);
        set_attribute(pte, _PAGE_PRESENT | _PAGE_READ | _PAGE_WRITE |
                           _PAGE_USER | _PAGE_ACCESSED | _PAGE_DIRTY);
        page->count++;
        flush_tlb_all();
        return va;
    }

    /* the share window of this process is full */
    if(page->count == 0){
        free_user_page(page->pa);
        page->pa = 0;
    }
    return 0;
}

void shm_page_dt(uintptr_t addr)
{
    uintptr_t pgdir = (uintptr_t)current_running[cpu_id]->pgdir;
    PTE *pte = find_pte(ROUNDDOWN(addr, PAGE_SIZE), pgdir);

    if(pte == NULL || !get_attribute(*pte, _PAGE_PRESENT)){
        return;
    }

    /* only a page that really belongs to a share group may be detached,
     * otherwise a bogus address would silently unmap private memory */
    uintptr_t pa = get_pa(*pte);
    for(int i = 0; i < SHM_PAGE_NUM; i++){
        if(shm_page[i].count > 0 && shm_page[i].pa == pa){
            *pte = 0;
            flush_tlb_all();

            shm_page[i].count--;
            if(shm_page[i].count == 0){
                free_user_page(pa);
                shm_page[i].pa = 0;
            }
            return;
        }
    }
}

void handle_page_fault(regs_context_t *regs, uint64_t stval, uint64_t cause)
{
    /* Anything outside the user half of the Sv39 address space is a genuine
     * kernel bug; let the generic handler dump the context. */
    if(stval >= (1lu << (VPN2_SHIFT + PPN_BITS - 1))){
        handle_other(regs, stval, cause);
        return;
    }

    /* demand paging: give the faulting address a frame (or fetch it back
     * from the swap area) and let the instruction run again */
    alloc_page_helper(stval, (uintptr_t)current_running[cpu_id]->pgdir);
}

#include <os/list.h>
#include <os/mm.h>
#include <os/lock.h>
#include <os/sched.h>
#include <os/time.h>
#include <os/irq.h>
#include <os/binsem.h>
#include <os/smp.h>
#include <screen.h>
#include <stdio.h>
#include <assert.h>
#include <csr.h>
#include <user_programs.h>
#include <os/elf.h>

extern void __global_pointer$();

pcb_t pcb[NUM_MAX_TASK];
pcb_t kernel_pcb[NR_CPUS];
const pcb_t *core0_tp = &kernel_pcb[0];
const pcb_t *core1_tp = &kernel_pcb[1];
const ptr_t kernel_stack_0 = INIT_KERNEL_STACK + PAGE_SIZE;
const ptr_t kernel_stack_1 = INIT_KERNEL_STACK + 2 * PAGE_SIZE;

LIST_HEAD(ready_queue);
LIST_HEAD(sleep_queue);

/* current running task PCB */
pcb_t * volatile current_running[NR_CPUS];
pcb_t * volatile current_cpu_running;

/* global process id */
pid_t process_id = 2;

/* at most this many arguments are handed over to a new process */
#define MAX_EXEC_ARGC 16

/*
 * A brand new address space costs a few frames right away (the ELF image, the
 * first stack page and the kernel stack).  Refuse to exec instead of running
 * into an allocation that cannot be satisfied even by swapping.
 */
#define EXEC_MIN_FREE_PAGES 16

static void reclaim_pcb(pcb_t *task);

/*
 * Only modify PCB, current_running, process_id and ready_queue
 * DO NOT STORE OR RESTORE
 * trick: modify $tp in ret_from_exception to ensure
 * disable_preempt() and enable_preempt() modify the same PCB
 */
void scheduler(void)
{
    pcb_t *prev = current_running[cpu_id];
    pcb_t *next;
    pcb_t *dying = NULL;
    list_node_t *next_node;

    if (prev != &kernel_pcb[cpu_id]) {
        if (prev->status == TASK_RUNNING) {
            /* still runnable: back to the tail of the ready queue */
            prev->status = TASK_READY;
            prev->ready_tick = get_ticks();
            list_add_tail(&prev->list, &ready_queue);
        } else if (prev->status == TASK_KILLED) {
            /* it died on this core; its address space can only be torn down
             * once `satp` no longer points at it, so remember it for now */
            list_del(&prev->list);
            dying = prev;
        }
    }

    next_node = max_priority_node();
    if (next_node == NULL) {
        /* nothing this hart may run, go back to its idle task */
        next = &kernel_pcb[cpu_id];
    } else {
        list_del(next_node);
        next = list_entry(next_node, pcb_t, list);
    }

    next->status = TASK_RUNNING;
    next->cpu_id = cpu_id;
    current_running[cpu_id] = next;
    /* ret_from_exception restores the context of `current_cpu_running` */
    current_cpu_running = next;

    /* every task owns its own cursor position */
    screen_cursor_x[cpu_id] = next->cursor_x;
    screen_cursor_y[cpu_id] = next->cursor_y;

    /* install the address space of the new task; the kernel window is part
     * of every page table, so the code below keeps running just fine */
    set_satp(SATP_MODE_SV39, 0, ((uintptr_t)next->pgdir) >> NORMAL_PAGE_SHIFT);
    local_flush_tlb_all();

    if (dying != NULL) {
        free_process_user_page(dying->pgdir);
        dying->pgdir = (PTE*)PGDIR_PA;
        reclaim_pcb(dying);
    }
}

/*
 * Prepare the kernel stack of a brand new process so that ret_from_exception
 * drops it into `entry_point` in user mode with argc/argv in a0/a1.
 */
static void init_pcb_stack(ptr_t kernel_stack, ptr_t user_stack, ptr_t entry_point,
                           pcb_t *new_pcb, int argc, uintptr_t argv)
{
    regs_context_t *pt_regs = (regs_context_t *)(kernel_stack - sizeof(regs_context_t));
    new_pcb->kernel_sp = kernel_stack - sizeof(regs_context_t);

    /* the pcb slot may have been used before, do not inherit stale registers */
    memset(pt_regs, 0, sizeof(regs_context_t));

    /* initialization registers: ra, sp, gp, a0, a1, sstatus, sepc, sscratch */
    pt_regs->regs[1] = (reg_t)entry_point;       //ra
    pt_regs->regs[2] = (reg_t)user_stack;        //sp
    pt_regs->regs[3] = (reg_t)__global_pointer$; //gp
    pt_regs->regs[10] = (reg_t)argc;             //a0, argc of main()
    pt_regs->regs[11] = (reg_t)argv;             //a1, argv of main()
    pt_regs->sepc = (reg_t)entry_point;          //sepc
    pt_regs->sstatus = (reg_t)SR_SPIE;           //SPP = 0, SPIE = 1
    pt_regs->sscratch = (reg_t)new_pcb;          //sscratch = tp
}

/*
 * Copy the arguments of the caller onto the freshly created user stack of
 * `new_pcb` and return the user virtual address of the argv array.  The page
 * is filled in through the kernel's direct mapping, which is reachable no
 * matter which address space is currently installed.
 */
static uintptr_t init_user_stack(pcb_t *new_pcb, int argc, char *argv[])
{
    uintptr_t top_va = USER_STACK_ADDR;
    uintptr_t top_kva = alloc_page_helper(top_va - PAGE_SIZE,
                                          (uintptr_t)new_pcb->pgdir) + PAGE_SIZE;
    /* the last `top_va - va` bytes of the page hold the address `va` */
    #define STACK_KVA(va) (top_kva - (top_va - (uintptr_t)(va)))

    uintptr_t string_va[MAX_EXEC_ARGC];
    uintptr_t sp = top_va;
    int i;

    /* the strings themselves, topmost first */
    for (i = argc - 1; i >= 0; i--) {
        int len = strlen(argv[i]) + 1;
        sp -= len;
        memcpy((uint8_t *)STACK_KVA(sp), (const uint8_t *)argv[i], (uint32_t)len);
        string_va[i] = sp;
    }

    /* then the NULL terminated array pointing at them */
    sp = ROUNDDOWN(sp, sizeof(uintptr_t));
    sp -= (argc + 1) * sizeof(uintptr_t);
    uintptr_t *slot = (uintptr_t *)STACK_KVA(sp);
    for (i = 0; i < argc; i++) {
        slot[i] = string_va[i];
    }
    slot[argc] = 0;

    uintptr_t argv_va = sp;
    /* the RISC-V ABI wants a 16 byte aligned stack pointer */
    new_pcb->user_sp = ROUNDDOWN(sp, 16);

    #undef STACK_KVA
    return argv_va;
}

/*
 * Load the ELF image called `file_name` into a brand new address space and
 * make it a runnable process.  The return value is the one the shell expects:
 * -1 when there is no such program, 0 when the process table is full, -2 when
 * memory ran out and the new pid on success.
 */
pid_t do_exec(const char* file_name, int argc, char* argv[], spawn_mode_t mode)
{
    disable_preempt();
    /* file_name and argv live in the caller's user space */
    enable_sum();

    unsigned char *binary = NULL;
    int length = 0;
    if (file_name == NULL || !get_elf_file(file_name, &binary, &length)) {
        disable_sum();
        enable_preempt();
        return -1;
    }

    /* clamp once, so that the array built on the user stack and the `argc`
     * handed to main() can never disagree */
    if (argc < 0 || argv == NULL) {
        argc = 0;
    }
    if (argc > MAX_EXEC_ARGC) {
        argc = MAX_EXEC_ARGC;
    }

    /* look for a free pcb: `pid == -1` marks an unused slot */
    int i;
    for (i = 0; i < NUM_MAX_TASK; i++) {
        if (pcb[i].pid == -1) {
            break;
        }
    }
    if (i == NUM_MAX_TASK) {
        disable_sum();
        enable_preempt();
        return 0;
    }

    if (free_page_num() < EXEC_MIN_FREE_PAGES) {
        disable_sum();
        enable_preempt();
        return -2;
    }

    pcb_t *new_pcb = &pcb[i];
    new_pcb->pgdir = init_page_table();
    /* the kernel stack is a pinned physical page used through the direct map */
    new_pcb->kernel_sp = pa2kva(alloc_user_page(1, NULL) + PAGE_SIZE);
    new_pcb->kernel_stack_base = new_pcb->kernel_sp;
    new_pcb->user_sp = USER_STACK_ADDR;
    new_pcb->user_stack_base = USER_STACK_ADDR;
    new_pcb->preempt_count = 0;
    init_list_head(&new_pcb->wait_list);
    init_list_head(&new_pcb->timer.list);
    new_pcb->binsem_num = 0;
    new_pcb->pid = process_id++;
    new_pcb->type = USER_PROCESS;
    new_pcb->status = TASK_READY;
    new_pcb->mode = mode;
    new_pcb->priority = 1;
    new_pcb->ready_tick = get_ticks();
    /* a child may run wherever its parent was allowed to run */
    new_pcb->mask = current_running[cpu_id]->mask;
    if (new_pcb->mask == 0) {
        new_pcb->mask = (1UL << NR_CPUS) - 1;
    }
    new_pcb->cpu_id = cpu_id;
    new_pcb->cursor_x = 1;
    new_pcb->cursor_y = 1;

    uintptr_t entry = load_elf(binary, (unsigned)length,
                               (uintptr_t)new_pcb->pgdir, alloc_page_helper);
    uintptr_t argv_va = init_user_stack(new_pcb, argc, argv);

    init_pcb_stack(new_pcb->kernel_sp, new_pcb->user_sp, entry,
                   new_pcb, argc, argv_va);
    list_add_tail(&new_pcb->list, &ready_queue);

    pid_t new_pid = new_pcb->pid;
    disable_sum();
    enable_preempt();
    return new_pid;
}

/* Give up every binary semaphore `task` still holds and hand each of them to
 * the next waiter, so that nobody stays blocked on a dead process. */
static void release_binsem(pcb_t *task)
{
    while (task->binsem_num > 0) {
        int id = task->binsem_id[--task->binsem_num];
        binsem_node_t *node = &binsem_nodes[id];

        node->sem++;
        if (node->sem <= 0 && !list_empty(&node->block_queue)) {
            list_node_t *heir_node = node->block_queue.next;
            pcb_t *heir = list_entry(heir_node, pcb_t, list);
            heir->binsem_id[heir->binsem_num++] = id;
            do_unblock(heir_node);
